import functools, random

def retry(max_attempts=4, base_delay=0.2, max_delay=2.0, jitter=True, sleep=time.sleep):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(1, max_attempts + 1):
                wrapper.last_attempts = attempt
                try:
                    return fn(*args, **kwargs)
                except (RetryableError, httpx.TimeoutException, httpx.ConnectError) as e:
                    last = e
                    if attempt == max_attempts:
                        raise
                    delay = min(max_delay, base_delay * 2 ** (attempt - 1))
                    if jitter:
                        delay *= random.uniform(0.5, 1.5)
                    sleep(delay)
            raise last  # unreachable, keeps type checkers calm
        wrapper.last_attempts = 0
        return wrapper
    return decorator
